public sealed record Employment(Company Company, DateInterval Effective)
{
    public bool IsEffectiveOn(LocalDate asOf) => Effective.Contains(asOf);

    public Employment End(LocalDate lastDay) =>
        this with { Effective = new DateInterval(Effective.Start, lastDay) };
}

